async function readSheet(file){const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const ws=wb.worksheets[0];const val=c=>{const v=c.value;return v&&typeof v==='object'?(v.result!==undefined?v.result:v.text||(v.richText||[]).map(t=>t.text).join('')):v};
 let head=null;const out=[];ws.eachRow(row=>{const cells=[];row.eachCell({includeEmpty:true},(c,i)=>cells[i]=val(c));if(!head){if(cells.some(c=>/code|item/i.test(String(c)))&&cells.some(c=>/qty|quantity/i.test(String(c))))head=cells.map(c=>String(c||'').trim().toLowerCase());return}const o={};head.forEach((h,i)=>{if(h)o[h]=cells[i]});out.push(o)});
 if(!head)throw new Error('No header row found. Use the template columns.');return out}
async function readAllSheets(file){const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const val=c=>{const v=c.value;if(v instanceof Date)return v;return v&&typeof v==='object'?(v.result!==undefined?v.result:v.text||(v.richText||[]).map(t=>t.text).join('')):v};return wb.worksheets.map(ws=>{const rows=[];ws.eachRow({includeEmpty:true},(row,n)=>{const c=[];for(let i=1;i<=ws.actualColumnCount+2&&i<=row.cellCount;i++)c[i-1]=val(row.getCell(i));rows[n-1]=c});return {name:ws.name,rows}})}
const pick=(o,...names)=>{for(const n of names)for(const k of Object.keys(o))if(k.includes(n))return o[k];return ''};

/* ---------- dialogs ---------- */
function dialog(html,onSubmit,onCancel){const d=document.createElement('dialog');d.innerHTML=`<form method="dialog" class="stack" autocomplete="off">${html}<div class="row"><button class="btn primary" value="ok">Save</button><button class="btn" value="cancel" formnovalidate>Cancel</button></div></form>`;document.body.append(d);d.addEventListener('close',()=>{if(d.returnValue==='ok'){const data=Object.fromEntries([...new FormData(d.querySelector('form'))].map(([k,v])=>[k.replace(/^vl_/,''),v]));onSubmit(data)}else if(onCancel)onCancel();d.remove()});d.showModal()}
const dInput=(n,l,v='',req=true,t='text')=>`<label class="field"><span>${l}</span><input name="vl_${n}" type="${t}" value="${esc(v)}" autocomplete="${t==='password'?'new-password':'off'}" ${req?'required':''}></label>`;
const dSel=(n,l,o,v)=>`<label class="field"><span>${l}</span><select name="vl_${n}">${o.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
function openSettings(){dialog(`<h2>AI settings</h2><p class="small muted">The free route needs no key. For the paid route, paste an API key. It stays in this browser and goes only to the AI provider. Costs depend on use: a breakdown is under one US cent; a drawing take-off costs more with page count.</p>${dInput('key','API key',getKey(),false,'password')}`,d=>{setKey(d.key.trim());toast(d.key?'API key saved in this browser.':'API key removed.')})}
function newChange(){const k=K();dialog(`<h2>New change</h2>${dInput('title','Title')}${dSel('kind','Starts as',STAGES,'DCR')}${dInput('no','Reference number','',false)}${dSel('reason','Reason',REASONS,'Design change')}${dInput('reasonRef','Reason reference (letter, email or RFI)','',false)}<label class="field"><span>General description</span><textarea name="description"></textarea></label>`,d=>{const n=k.changes.length+1,id=`CE-${k.code.replace(/\W/g,'')}-${String(n).padStart(3,'0')}`.toUpperCase();k.changes.push({id,title:d.title,description:d.description,reason:d.reason,reasonRef:d.reasonRef,discipline:'',abortive:{status:'Not applicable'},si:[],lines:[],stages:[{kind:d.kind,no:d.no,date:new Date().toISOString().slice(0,10),status:'Draft',amount:0,approved:'',letterRef:'',deltaReason:''}]});save();go({p:view.p,k:view.k,c:id})})}
function newVO(){const k=K();k.vos=k.vos||[];const used=new Set(k.vos.flatMap(v=>v.items.map(i=>i.changeId)));const free=k.changes.filter(c=>!used.has(c.id)&&!(c.stages||[]).some(s=>s.status==='Cancelled'));dialog('<h2>Create variation order</h2>'+dInput('no','VO number','VO-'+String(k.vos.length+1).padStart(2,'0'))+dInput('date','Date',today(),true,'date')+dInput('cpa','CPA number','',false)+'<fieldset class="stack" style="border:1px solid var(--line);max-height:280px;overflow:auto"><legend class="small">Include these changes</legend>'+free.map(c=>{const cr=(c.stages||[]).find(s=>s.kind==='CR')||{};return '<label class="row small" style="flex-wrap:nowrap;align-items:flex-start"><input type="checkbox" name="pick_'+c.id+'"><span>'+esc(cr.no||c.id)+' · '+esc(c.title.slice(0,70))+' · '+money(E.changeValue(c,k).assessed)+'</span></label>'}).join('')+'</fieldset>',d=>{const ids=Object.keys(d).filter(x=>x.startsWith('pick_')).map(x=>x.slice(5));if(!ids.length)return toast('Choose at least one change.');const vo={id:uid('v'),no:d.no,date:d.date,cpa:d.cpa,status:'Draft',items:ids.map(id=>{const c=k.changes.find(x=>x.id===id),amt=E.changeValue(c,k).assessed;c.stages.push({kind:'VO',no:d.no,date:d.date,status:'Draft',amount:amt,approved:'',letterRef:'',deltaReason:'Final assessment in '+d.no});return {changeId:id,amount:amt}})};k.vos.push(vo);view.tab='vos';save();render();toast(d.no+' created with '+ids.length+' changes.')})}
function convertStage(){const k=K(),c=C(),net=E.computeChange(c,k).net,last=E.latestStage(c)||{},moved=E.round2(net-E.num(last.amount));const next=last.kind==='VO'?'VO':last.kind==='CR'?'VO':'CR';
 dialog(`<h2>Move to next stage</h2><p>This keeps the title <strong>${esc(c.title)}</strong> and freezes today's assessment of <span class="mono">${money(net)}</span>.</p>${moved?`<div class="alert">This is ${money(moved)} different from ${esc(last.kind)} ${esc(last.no)}. Give the reason below.</div>`:''}${dSel('kind','New stage',STAGES,next)}${dInput('no','Number')}${dInput('date','Date',new Date().toISOString().slice(0,10),true,'date')}<label class="field"><span>Reason for move</span><textarea name="reason" ${moved?'required':''}></textarea></label>`,d=>{c.stages.push({kind:d.kind,no:d.no,date:d.date,status:'Draft',amount:net,approved:'',letterRef:'',deltaReason:d.reason});save();view.tab='chain';render();toast(`${d.kind} ${d.no} linked to ${c.id}`)})}

/* ---------- events ---------- */
function bind(path,v,el){const k=K(),c=C(),a=path.split('.');const nums=['riskPct','takeoffQty','executedQty','contractorQty','contractorRate','rate','factor','qty','amount','approved','markupPct','vatPct'];const cast=f=>el.type==='checkbox'?el.checked:nums.includes(f)&&v!==''?Number(v):v;
 if(a[0]==='pkg')k[a[1]]=a[1]==='contractAmount'?(v===''?null:Number(v)):v;else if(a[0]==='c')k.contract[a[1]]=cast(a[1]);else if(a[0]==='boq')k.boq[+a[1]][a[2]]=cast(a[2]);else if(a[0]==='line')c.lines[+a[1]][a[2]]=cast(a[2]);else if(a[0]==='bd')c.lines[+a[1]].breakdown[+a[2]][a[3]]=cast(a[3]);else if(a[0]==='st')c.stages[+a[1]][a[2]]=cast(a[2]);else if(a[0]==='si')c.si[+a[1]][a[2]]=v;else if(a[0]==='ch')c[a[1]]=a[1]==='riskPct'?(v===''?null:Number(v)):v;else if(a[0]==='cl')k.clauses[+a[1]][a[2]]=v;else if(a[0]==='ty')k.types[+a[1]][a[2]]=a[2]==='count'?Number(v):v;else if(a[0]==='fi')c.findings[+a[1]][a[2]]=v;else if(a[0]==='vo'){const vo=k.vos[+a[1]],it=vo.items[+a[2]];it.amount=Number(v);syncVO(vo)}else if(a[0]==='ab'){c.abortive=c.abortive||{};c.abortive[a[1]]=v}
 save();render()}
function syncVO(vo){const k=K();vo.items.forEach(it=>{const c=k.changes.find(x=>x.id===it.changeId);if(!c)return;const s=(c.stages||[]).find(x=>x.kind==='VO'&&x.no===vo.no);if(s){s.amount=E.num(it.amount);s.status=vo.status==='Approved'?'Approved':'Draft';s.approved=vo.status==='Approved'?E.num(it.amount):''}})}
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.bind){bind(t.dataset.bind,t.value,t);return}
 if(t.dataset.clauseLink){const c=C(),id=t.dataset.clauseLink;c.clauseOff=(c.clauseOff||[]).filter(x=>x!==id);c.clauseOn=(c.clauseOn||[]).filter(x=>x!==id);(t.checked?c.clauseOn:c.clauseOff).push(id);save();return render()}
 if(t.dataset.act==='smart'){const fs=[...t.files];t.value='';return smartFiles(fs,t.dataset.hint)}
 if(t.dataset.act==='newDrawings'){const fs=[...t.files];t.value='';for(const f of fs)await addDoc(f,'New drawing',{});render();return toast(fs.length+' new drawings saved with this change.')}
 if(t.dataset.doc){const f=t.files[0];const cat=t.dataset.doc;t.value='';if(!f)return;try{const r=await addLibrary(f,cat);render();toast(r.scanned?'Saved. Scanned, so AI needs it attached.':r.chunks+' sections indexed.')}catch(err){toast(err.message||'The file could not be read.')}return}
 const f=t.files&&t.files[0];if(!f)return;
 try{ if(t.dataset.doc){const k=K();k.docs.push({category:t.dataset.doc,name:f.name,rev:'',date:new Date(f.lastModified).toISOString().slice(0,10)});save();render();return}
  if(t.dataset.act==='importJson'){const j=JSON.parse(await f.text());if(!j.id||!j.packages)throw new Error('This is not a VariLink project file.');const i=state.projects.findIndex(p=>p.id===j.id);i>=0?state.projects[i]=j:state.projects.push(j);save();go({p:j.id});return}
 }catch(err){toast(err.message||'The file could not be read.')}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,tr.link');if(!b)return;const d=b.dataset,k=K(),c=C();
 try{
 if(d.delProject){const pr=state.projects.find(x=>x.id===d.delProject);return dialog(`<h2>Delete project</h2><p>This removes <strong>${esc(pr.name)}</strong> and all its packages from this browser. Type DELETE to confirm.</p>${dInput('ok','Confirmation')}`,x=>{if(x.ok.trim().toUpperCase()!=='DELETE')return toast('Project kept.');state.projects=state.projects.filter(y=>y.id!==pr.id);save();go({});toast('Project deleted.')})}
 if(d.go==='home')return go({});if(d.go==='p')return go({p:view.p});if(d.go==='k')return go({p:view.p,k:view.k});
 if(d.openProject)return go({p:d.openProject});if(d.openPackage)return go({p:view.p,k:d.openPackage});if(d.openChange)return go({p:view.p,k:view.k,c:d.openChange});
 if(d.tab){view.tab=d.tab;try{location.hash='v-'+[view.p,view.k,view.c&&view.c.toLowerCase(),view.tab].map(x=>x||'x').join('-')}catch(x){}return render()}
 if(d.addLine){c.lines.push(d.addLine==='Omission'?{id:uid('l'),action:'Omission',scope:'partial',boqCode:'',takeoffQty:''}:{id:uid('l'),action:'Addition',desc:'',unit:'',takeoffQty:'',rateSource:'BOQ',rateRef:''});save();return render()}
 if(d.delLine){c.lines.splice(+d.delLine,1);save();return render()}
 if(d.useRate){const [i,code]=d.useRate.split('|');const l=c.lines[+i];if(l.action==='Omission'){l.boqCode=code}else{l.rateSource='Similar';l.rateRef=code}save();return render()}
 if(d.cand){const [act,code]=d.cand.split('|');const b=E.findBoq(k,code);c.lines.push(act==='Omission'?{id:uid('l'),action:'Omission',scope:'partial',boqCode:code,takeoffQty:''}:{id:uid('l'),action:'Addition',desc:b.desc,unit:b.unit,discipline:b.discipline,takeoffQty:'',rateSource:'BOQ',rateRef:code});save();return render()}
 if(d.delClause){k.clauses.splice(+d.delClause,1);save();return render()}
 if(d.delType){k.types.splice(+d.delType,1);save();return render()}
 if(d.delCdoc){c.docs.splice(+d.delCdoc,1);save();return render()}
 if(d.getFile){const f=await getFile(d.getFile);if(!f)return toast('This file is not in this browser.');return await saveBlob(f.name,f.blob)}
 if(d.voApprove){const v=k.vos[+d.voApprove];v.status=v.status==='Approved'?'Draft':'Approved';syncVO(v);save();return render()}
 if(d.voExport)return await exportVO(k.vos[+d.voExport]);
 if(d.delBoq){k.boq.splice(+d.delBoq,1);save();return render()}
 if(d.delDoc){k.docs.splice(+d.delDoc,1);save();return render()}
 if(d.delSi){c.si.splice(+d.delSi,1);save();return render()}
 if(d.addBd){const l=c.lines[+d.addBd];l.breakdown=l.breakdown||[];l.breakdown.push({cat:'Supply',item:'',unit:'',qty:1,rate:0});save();return render()}
 if(d.delBd){const [i,j]=d.delBd.split('.');c.lines[+i].breakdown.splice(+j,1);save();return render()}
 if(d.aiCopy){const t=aiPrompt(d.aiCopy);try{await navigator.clipboard.writeText(t);b.textContent='Copied. Now paste it in the chat';toast('Request copied.')}catch(x){const ta=document.getElementById('ai-reply-'+d.aiCopy);ta.value=t;ta.select();toast('Copy this request from the box.')}return}
 if(d.aiSample){document.getElementById('ai-reply-'+d.aiSample).value=SAMPLE_REPLY();return aiApply(d.aiSample)}
 if(d.aiApply)return aiApply(d.aiApply);if(d.aiRun)return await aiRun(d.aiRun);
 switch(d.act){
  case 'settings':return openSettings();
  case 'newProject':return dialog(`<h2>New project</h2>${dInput('name','Project name')}${dInput('client','Client')}${dInput('currency','Currency','EGP')}`,x=>{const id=uid('p');state.projects.push({id,name:x.name,client:x.client,currency:x.currency,packages:[]});save();go({p:id})});
  case 'newPackage':return dialog(`<h2>New package</h2>${dInput('code','Package code','PK-')}${dInput('name','Package name')}${dInput('contractor','Contractor')}${dSel('type','Contract type',CONTRACTS,'Lump Sum')}`,x=>{const id=uid('k');P().packages.push({id,code:x.code,name:x.name,contractor:x.contractor,contract:{type:x.type,typeOther:'',markupPct:30,vatPct:14,designFeesIncluded:'No',iftIsIfc:'Yes',geotech:'Yes',pricingClause:'',paymentClause:'',notes:''},docs:[],boq:[],changes:[]});save();go({p:view.p,k:id,tab:'contract'})});
  case 'newChange':return newChange();case 'convert':return convertStage();
  case 'addClause':k.clauses=k.clauses||[];k.clauses.push({id:uid('c'),topic:'Variation pricing',ref:'',text:''});save();return render();
  case 'addType':k.types=k.types||[];k.types.push({name:'',count:1});save();return render();
  case 'newVO':return newVO();
  case 'analyse':return await analyseChange();
  case 'addBoq':k.boq.push({code:'',desc:'',unit:'',qty:0,rate:0,discipline:''});save();return render();
  case 'addSi':c.si=c.si||[];c.si.push({no:'',date:'',ref:''});save();return render();
  case 'exportVA':return await exportVA();case 'exportLog':return await exportLog();case 'exportProjectLog':return await exportProjectLog();
  case 'exportJson':{const p=P();return await saveBlob(`${p.name}.varilink.json`,new Blob([JSON.stringify(p,null,1)],{type:'application/json'}))}
  case 'tplBoq':return await template('BOQ template.xlsx',['Code','Description','Unit','Qty','Rate','Discipline'],[['F-101','Sample item','m2',100,250,'Finishes']]);
  case 'tplTakeoff':return await template('Take-off template.xlsx',['Code','Description','Unit','Original Qty','Revised Qty'],[['F-101','Sample item','m2',100,80]]);
  case 'applyTakeoff':{let n=0;takeoffRows.filter(r=>r.action).forEach(r=>{const q=Math.abs(r.delta);if(r.action==='Omission')c.lines.push({id:uid('l'),action:'Omission',scope:r.scope,boqCode:r.boq?r.code:'',takeoffQty:q});else c.lines.push({id:uid('l'),action:'Addition',desc:r.desc||(r.boq&&r.boq.desc)||'',unit:r.unit||(r.boq&&r.boq.unit)||'',takeoffQty:q,rateSource:r.boq?'BOQ':'Manual',rateRef:r.boq?r.code:'',discipline:r.boq&&r.boq.discipline});n++});takeoffRows=null;save();render();return toast(`${n} lines created.`)}
 }}catch(err){toast(err.message||'That action failed.')}});
window.addEventListener('hashchange',()=>{const b=JSON.stringify(view);fromHash();if(JSON.stringify(view)!==b)render()});
document.addEventListener('input',e=>{const m=(e.target.id||'').match(/^ai-reply-(.+)/);if(m)aiText[m[1]]=e.target.value});
document.addEventListener('paste',e=>{const m=(e.target.id||'').match(/^ai-reply-(.+)/);if(m)setTimeout(()=>{if(/\{[\s\S]*\}/.test(e.target.value))aiApply(m[1])},0)});
$('#brand').addEventListener('click',()=>go({}));
fromHash();if(!view.p&&state.projects.length)view={p:state.projects[0].id,k:null,c:null,tab:null};render();
